mutants.inicia_zero:
def maior_valor(valores):
    maior = 0
    for valor in valores:
        if valor > maior:
            maior = valor
    return maior

mutants.comparacao_invertida:
def maior_valor(valores):
    maior = valores[0]
    for valor in valores[1:]:
        if valor < maior:
            maior = valor
    return maior

mutants.retorno_precoce:
def maior_valor(valores):
    maior = valores[0]
    for valor in valores[1:]:
        if valor > maior:
            maior = valor
        return maior
    return maior
